return function()
	local parentModule = require(script.Parent)
	it("Should be able to access the raw API dump", function()
		local apiDump = parentModule.FetchApiDump()
		expect(apiDump).never.to.equal(nil)
		expect(apiDump.Classes).never.to.equal(nil)
		expect(apiDump.Version).never.to.equal(nil)
	end)
	it("Should be able to fetch all classes from the raw API dump", function()
		local allClasses = parentModule.FetchAllClasses()
		expect(#allClasses).never.to.equal(0)
		expect(table.find(allClasses, "Workspace")).never.to.equal(nil)
	end)
	it("Should be able to query class names", function()
		expect(parentModule.IsClassRegistered("Workspace")).to.equal(true)
		expect(parentModule.IsClassRegistered("FakeWorkspace")).to.equal(false)
	end)
	it("Should be able to query class members", function()
		local classMembers = parentModule.FetchClassMembers("Workspace")
		expect(#classMembers).never.to.equal(0)

		for _, classMember in classMembers do
			expect(workspace[classMember]).never.to.equal(nil)
		end
	end)
	it("Should be able to fetch the member type from a class", function()
		local classMemberType = parentModule.FetchClassMemberType("Workspace", "Gravity")
		expect(classMemberType).to.equal("Property")
	end)
	it("Should be able to fetch the tags for a member of a class", function()
		local classMemberTags = parentModule.FetchClassMemberTags("Workspace", "StreamingMinRadius")
		expect(classMemberTags.NotScriptable).to.equal(true)
	end)
	it("Should be able to fetch the security for a member of a class", function()
		local classMemberSecurity = parentModule.FetchClassMemberSecurity("Workspace", "StreamingEnabled")
		expect(classMemberSecurity.Read).to.equal("None")
		expect(classMemberSecurity.Write).to.equal("PluginSecurity")
	end)
	it("Should be able to fetch the thread safety for a member of a class", function()
		local classMemberThreadSafety = parentModule.FetchClassMemberThreadSafety("Workspace", "StreamingEnabled")
		expect(classMemberThreadSafety).to.equal("ReadSafe")
	end)
	it("Should be able to query class superclass", function()
		local classSuperclass = parentModule.FetchClassSuperclass("Workspace")
		expect(classSuperclass).to.equal("WorldRoot")
	end)
	it("Should be able to query class superclasses", function()
		local classSuperclasses = parentModule.FetchClassSuperclasses("Workspace")
		expect(#classSuperclasses).never.to.equal(0)
		expect(classSuperclasses[#classSuperclasses]).to.equal("<<<ROOT>>>")
		expect(classSuperclasses[1]).to.equal("WorldRoot")
	end)
end